#include <bits/stdc++.h>
using namespace std;

const int INF = INT_MAX;

namespace flow {

const int MAXN = 10001;
struct Edge { int v, p; int c, w; };
vector<Edge> graph[MAXN];
int visited[MAXN], current[MAXN], nodeCount;
int dist[MAXN], potential[MAXN];

int addVertices(int count) {
    while (count--) graph[nodeCount++].clear();
    return nodeCount - 1;
}

void addEdge(int u, int v, int capacity, int weight) {
    graph[u].push_back({ v, (int)graph[v].size(), capacity, weight });
    graph[v].push_back({ u, (int)graph[u].size() - 1, 0, -weight });
}

bool dijkstra(int start, int end) {
    fill_n(dist, nodeCount, INF);
    fill_n(visited, nodeCount, 0);
    typedef pair<int, int> pli;
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    pq.push({ dist[start] = 0, start });
    while (!pq.empty()) {
        int u, du; tie(du, u) = pq.top(); pq.pop();
        if (visited[u]) continue; visited[u] = 1;
        for (auto &edge : graph[u]) {
            int v = edge.v; int dv = du + potential[u] + edge.w - potential[v];
            if (!edge.c || visited[v] || dist[v] <= dv) continue;
            pq.push({ dist[v] = dv, v });
        }
    }
    return visited[end];
}

bool bfsLevelGraph(int start, int end) {
    fill_n(visited, nodeCount, 0);
    queue<int> q; q.push(start); visited[start] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto &e : graph[u]) {
            int v = e.v;
            if (visited[v] || !e.c) continue;
            if (dist[v] != dist[u] + e.w - potential[v] + potential[u]) continue;
            visited[v] = visited[u] + 1; q.push(v);
        }
    }
    return visited[end] != 0;
}

int dfsFlow(int u, int t, int flow) {
    if (u == t) return flow;
    int totalFlow = 0;
    for (int &i = current[u]; i < (int)graph[u].size(); ++i) {
        auto &e = graph[u][i]; int v = e.v;
        if (!e.c || visited[v] != visited[u] + 1) continue;
        if (dist[v] != dist[u] + e.w - potential[v] + potential[u]) continue;
        int pushed = dfsFlow(v, t, min(e.c, flow));
        totalFlow += pushed; flow -= pushed; e.c -= pushed; graph[v][e.p].c += pushed;
        if (!flow) break;
    }
    return totalFlow;
}

pair<int, int> minCostMaxFlow(int s, int t, int maxFlow) {
    int flowSum = 0, costSum = 0;
    fill_n(potential, nodeCount, 0);
    while (dijkstra(s, t)) {
        int flow = 0;
        while (bfsLevelGraph(s, t)) {
            fill_n(current, nodeCount, 0);
            int pushedFlow = dfsFlow(s, t, maxFlow);
            maxFlow -= pushedFlow; flow += pushedFlow;
            if (!maxFlow) break;
        }
        flowSum += flow; costSum += (dist[t] + potential[t]) * flow;
        for (int i = 0; i < nodeCount; ++i) potential[i] += dist[i];
        if (!maxFlow) break;
    }
    return { flowSum, costSum };
}

}

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    int totalVertices = max(n, k) * 2;
    flow::addVertices(totalVertices * n);
    int source = flow::addVertices(1), sink = flow::addVertices(1);
    for (int j = 0; j < k; ++j) {
        int a; scanf("%d", &a);
        a--;
        flow::addEdge(source, a, 1, 0);
    }
    for (int z = 1; z <= m; ++z) {
        int u, v; scanf("%d %d", &u, &v);
        u--; v--;
        for (int i = 0; i + 1 < totalVertices; ++i) {
            int u1 = u + i * n, v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n, v2 = v + i * n;
            for (int j = 0; j < k; ++j) {
                flow::addEdge(u1, v1, 1, c + d * (2 * j + 1));
                flow::addEdge(v2, u2, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i + 1 < totalVertices; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n, v = j + (i + 1) * n;
            flow::addEdge(u, v, INF, c);
        }
    }
    for (int i = 0; i < totalVertices; ++i)
        flow::addEdge(i * n, sink, INF, 0);
    printf("%d\n", flow::minCostMaxFlow(source, sink, INF).second);
    return 0;
}
